import { KeystoneContext } from "@keystone-6/core/types";
import { PIPELINE_STATUS } from "../../../models/Saas/Tech/crm/constants";
import { haversineDistance } from "../../../utils/helpers/calculate_distances";
import { buildReviewsAndPrompt } from "../../../utils/helpers/tech/build_prompt_text";
import { parseAddressComponents } from "../../../utils/helpers/tech/parse_address";
import { getRemainingCredits } from "../../../utils/helpers/tech/remaining_credits";
import { consumeCompanyCredits } from "../../../utils/saas/companyCredits";
import { getPlaceDetails } from "../../../utils/helpers/tech/place_details";

/**
 * syncLeadsFront: asigna TechBusinessLead a la SaasCompany del usuario.
 * Relación N:M: un mismo lead puede estar en varias companies; solo usamos connect (nunca set/disconnect).
 * Mismo punto (lat/lng/radius/category) debe dar el mismo pool de leads para cualquier company.
 */
/** Asegura que exista TechStatusBusinessLead para este lead + company con salesPerson; crea o actualiza. */
async function ensureStatusForLeadAssignment(
  context: KeystoneContext,
  leadId: string,
  companyId: string,
  userId: string,
  opportunityLevel: "Alta" | "Media" | "Baja" = "Media",
): Promise<void> {
  const [existing] = await context
    .sudo()
    .query.TechStatusBusinessLead.findMany({
      where: {
        businessLead: { id: { equals: leadId } },
        saasCompany: { id: { equals: companyId } },
      },
      take: 1,
      query: "id",
    });
  if (existing) {
    await context.sudo().query.TechStatusBusinessLead.updateOne({
      where: { id: (existing as { id: string }).id },
      data: {
        salesPerson: { connect: { id: userId } },
        pipelineStatus: PIPELINE_STATUS.DETECTADO,
        opportunityLevel,
      },
    });
  } else {
    await context.sudo().query.TechStatusBusinessLead.createOne({
      data: {
        businessLead: { connect: { id: leadId } },
        saasCompany: { connect: { id: companyId } },
        salesPerson: { connect: { id: userId } },
        pipelineStatus: PIPELINE_STATUS.DETECTADO,
        opportunityLevel,
      },
    });
  }
}

const MIN_RATING = 0;
const MIN_REVIEWS = 0;
const DEFAULT_MAX_RESULTS = 60;

type SyncLeadsResult = {
  success: boolean;
  message: string;
  created: number;
  alreadyInDb: number;
  skippedLowRating: number;
  syncedLeadsCount: number;
  syncedCount: number | null;
  leadLimit: number | null;
};

async function logSyncLeadsResult(
  context: KeystoneContext,
  userId: string | undefined,
  companyId: string | undefined,
  input: { lat: number; lng: number; radius: number; category: string },
  result: SyncLeadsResult,
): Promise<void> {
  if (!userId) return;
  try {
    await context.sudo().query.TechLeadSyncLog.createOne({
      data: {
        user: { connect: { id: userId } },
        ...(companyId && { company: { connect: { id: companyId } } }),
        success: result.success,
        message: result.message,
        created: result.created,
        alreadyInDb: result.alreadyInDb,
        skippedLowRating: result.skippedLowRating,
        syncedLeadsCount: result.syncedLeadsCount,
        syncedCount: result.syncedCount,
        leadLimit: result.leadLimit,
        lat: input.lat,
        lng: input.lng,
        radius: input.radius,
        category: input.category,
      },
    });
  } catch (_) {}
}

const typeDefs = `
  input SyncLeadsFrontInput {
    lat: Float!
    lng: Float!
    radius: Float!
    category: String!
    maxResults: Int
    minRating: Float
    minReviews: Int
  }

  type SyncLeadsFrontResult {
    success: Boolean!
    message: String!
    created: Int!
    alreadyInDb: Int!
    skippedLowRating: Int!
    syncedLeadsCount: Int!
    syncedCount: Int
    leadLimit: Int
  }

  type Mutation {
    syncLeadsFront(input: SyncLeadsFrontInput!): SyncLeadsFrontResult!
  }
`;

const definition = `
  syncLeadsFront(input: SyncLeadsFrontInput!): SyncLeadsFrontResult!
`;

const resolver = {
  syncLeadsFront: async (
    _root: unknown,
    {
      input,
    }: {
      input: {
        lat: number;
        lng: number;
        radius: number;
        category: string;
        maxResults?: number;
        minRating?: number;
        minReviews?: number;
      };
    },
    context: KeystoneContext,
  ) => {
    const emptyResult = {
      created: 0,
      alreadyInDb: 0,
      skippedLowRating: 0,
      syncedLeadsCount: 0,
      syncedCount: null as number | null,
      leadLimit: null as number | null,
    };

    const session = context.session as { data?: { id: string } } | undefined;
    const userId = session?.data?.id;
    // #region agent log
    console.log("[syncLeadsFront] START", {
      userId: userId ?? null,
      lat: input?.lat,
      lng: input?.lng,
      radius: input?.radius,
      category: input?.category,
      maxResults: input?.maxResults,
    });
    fetch('http://127.0.0.1:7352/ingest/c13a22b4-961b-4030-9e07-9a1b167ba855',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'0a11d1'},body:JSON.stringify({sessionId:'0a11d1',runId:'pre-fix',hypothesisId:'D',location:'syncLeadsFront.ts:entry',message:'syncLeadsFront called',data:{hasUserId:!!userId,lat:input?.lat,lng:input?.lng,radius:input?.radius,category:input?.category,maxResults:input?.maxResults},timestamp:Date.now()})}).catch(()=>{});
    // #endregion
    if (!userId) {
      return {
        success: false,
        message: "Debes iniciar sesión para sincronizar leads",
        ...emptyResult,
      };
    }

    const user = await context.sudo().query.User.findOne({
      where: { id: userId },
      query: "id company { id name }",
    });

    const company = (user as { company?: { id: string; name?: string } | null })
      ?.company;

    if (!company?.id) {
      const result = {
        success: false,
        message: "Tu usuario no tiene una empresa asignada",
        ...emptyResult,
      };
      await logSyncLeadsResult(context, userId, undefined, input, result);
      return result;
    }

    const credits = await getRemainingCredits(context, company.id);
    const { remainingQuota, syncedCount, leadLimit } = credits;
    const companyLabel = company?.name ?? "la empresa";

    if (credits.blockingReason === "no_subscription") {
      const result = {
        success: false,
        message: `"${company?.name ?? "La empresa"}" no tiene una suscripción activa. Contrata o activa una suscripción para sincronizar leads.`,
        ...emptyResult,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    if (credits.blockingReason === "free_plan_expired") {
      const result = {
        success: false,
        message:
          "Tu plan gratuito ha terminado. Contrata o activa una suscripción para poder obtener más clientes.",
        ...emptyResult,
        leadLimit: 0,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    if (credits.blockingReason === "no_lead_limit") {
      const result = {
        success: false,
        message: `La suscripción activa de "${companyLabel}" no tiene límite de leads configurado.`,
        ...emptyResult,
        leadLimit,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    if (credits.blockingReason === "lead_limit_too_low") {
      const result = {
        success: false,
        message: `La suscripción activa de "${companyLabel}" no permite sincronizar leads.`,
        ...emptyResult,
        leadLimit,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    if (remainingQuota === 0) {
      const result = {
        success: false,
        message: `Cuota mensual de tu suscripción alcanzada (${syncedCount}/${leadLimit} leads). Próximo reinicio el mes siguiente.`,
        ...emptyResult,
        syncedCount,
        leadLimit,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    const maxResults = Math.min(
      input.maxResults ?? DEFAULT_MAX_RESULTS,
      remainingQuota,
    );

    const minRating =
      typeof input.minRating === "number"
        ? Math.max(0, input.minRating)
        : MIN_RATING;
    const minReviews =
      typeof input.minReviews === "number"
        ? Math.max(0, Math.floor(input.minReviews))
        : MIN_REVIEWS;

    const {
      lat: centerLat,
      lng: centerLng,
      radius: radiusKm,
      category: inputCategory,
    } = input;

    // 1) Buscar TechBusinessLead en BD por categoría, dentro del radio; excluir los que ya están asignados a esta company
    console.log("[syncLeadsFront] DB search", {
      category: inputCategory,
      centerLat,
      centerLng,
      radiusKm,
      maxResults,
      remainingQuota,
    });
    const candidates = await context.sudo().query.TechBusinessLead.findMany({
      where: {
        category: { equals: inputCategory },
      },
      take: 1000,
      query: "id lat lng saasCompany { id }",
    });

    type LeadCandidate = {
      id: string;
      lat: number | null;
      lng: number | null;
      saasCompany?: { id: string }[];
    };
    const existingIds: string[] = [];
    for (const lead of candidates as LeadCandidate[]) {
      if (existingIds.length >= maxResults) break;
      const leadLat = lead.lat;
      const leadLng = lead.lng;
      if (leadLat == null || leadLng == null) continue;
      const distanceKm = haversineDistance(
        centerLat,
        centerLng,
        leadLat,
        leadLng,
      );
      if (distanceKm > radiusKm) continue;
      // No asignar si ya está asignado a esta company
      const alreadyAssignedToThisCompany = (lead.saasCompany ?? []).some(
        (c) => c.id === company.id,
      );
      if (alreadyAssignedToThisCompany) continue;
      existingIds.push(lead.id);
    }

    // Asignar siempre los leads existentes en el área a esta company (solo connect: un mismo lead puede estar en varias companies).
    let assignedFromDb = 0;
    for (const leadId of existingIds) {
      try {
        await context.sudo().query.TechBusinessLead.updateOne({
          where: { id: leadId },
          data: { saasCompany: { connect: { id: company.id } } }, // ADD only; never replace
        });
        await ensureStatusForLeadAssignment(
          context,
          leadId,
          company.id,
          userId,
        );
        assignedFromDb++;
      } catch (_) {}
    }
    let syncedThisRequest = assignedFromDb;
    let currentSyncedCount = syncedCount;
    console.log("[syncLeadsFront] after DB assign", {
      candidatesInCategory: (candidates as LeadCandidate[]).length,
      existingIdsInRadius: existingIds.length,
      assignedFromDb,
      syncedCount,
      leadLimit,
      remainingQuota,
    });
    if (assignedFromDb > 0) {
      const consumeResult = await consumeCompanyCredits(context, {
        companyId: company.id,
        amount: assignedFromDb,
        referenceType: "sync",
        notes: "Leads asignados desde BD",
      });
      if (!consumeResult.success) {
        const result = {
          success: false,
          message: `Cuota mensual alcanzada (${consumeResult.syncedCount}/${consumeResult.leadLimit} leads).`,
          ...emptyResult,
          syncedCount: consumeResult.syncedCount,
          leadLimit: consumeResult.leadLimit,
        };
        await logSyncLeadsResult(context, userId, company.id, input, result);
        return result;
      }
      currentSyncedCount = consumeResult.syncedCount;
    }

    // Si ya alcanzamos maxResults o la cuota, devolver (mismo pool de leads para cualquier company)
    if (
      syncedThisRequest >= maxResults ||
      (leadLimit !== null && currentSyncedCount >= leadLimit)
    ) {
      const result = {
        success: true,
        message: `${assignedFromDb} leads asignados. Cuota: ${currentSyncedCount}${leadLimit !== null ? `/${leadLimit}` : ""} este mes.`,
        created: 0,
        alreadyInDb: assignedFromDb,
        skippedLowRating: 0,
        syncedLeadsCount: assignedFromDb,
        syncedCount: currentSyncedCount,
        leadLimit,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    // Buscar más en Google Maps si hace falta (crear si no existe, asignar a la company; connect solo, nunca quitar otras companies).
    const apiKey = process.env.GOOGLE_MAPS_API_KEY;
    if (!apiKey) {
      if (syncedThisRequest > 0) {
        const result = {
          success: true,
          message: `${syncedThisRequest} leads asignados desde BD. GOOGLE_MAPS_API_KEY no configurada para buscar más. Cuota: ${currentSyncedCount}${leadLimit !== null ? `/${leadLimit}` : ""} este mes.`,
          created: 0,
          alreadyInDb: assignedFromDb,
          skippedLowRating: 0,
          syncedLeadsCount: syncedThisRequest,
          syncedCount: currentSyncedCount,
          leadLimit,
        };
        await logSyncLeadsResult(context, userId, company.id, input, result);
        return result;
      }
      const result = {
        success: false,
        message: "GOOGLE_MAPS_API_KEY no configurada",
        ...emptyResult,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }

    const { lat, lng, radius, category } = input;
    const radiusMeters = Math.round(radius * 1000);
    const keyword = encodeURIComponent(category);
    let created = 0;
    let alreadyInDb = assignedFromDb;
    let skippedLowRating = 0;
    // currentSyncedCount y syncedThisRequest ya vienen de la asignación de existingIds
    // #region agent log
    console.log("[syncLeadsFront] GOOGLE Nearby Search prep", {
      lat,
      lng,
      radius,
      radiusMeters,
      category,
      keyword,
      hasApiKey: !!apiKey,
      assignedFromDb,
      syncedThisRequest,
      maxResults,
    });
    fetch('http://127.0.0.1:7352/ingest/c13a22b4-961b-4030-9e07-9a1b167ba855',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'0a11d1'},body:JSON.stringify({sessionId:'0a11d1',runId:'post-fix',hypothesisId:'credits+pages',location:'syncLeadsFront.ts:beforeGoogle',message:'About to collect Google Nearby pages first',data:{lat,lng,radius,radiusMeters,category,keyword,assignedFromDb,syncedThisRequest,maxResults},timestamp:Date.now()})}).catch(()=>{});
    // #endregion

    /** Cobra créditos de leads Google ya sincronizados (evita leads gratis si falla después). */
    let googleCreditsCharged = false;
    const chargeGoogleCreditsIfNeeded = async () => {
      const googleSynced = syncedThisRequest - assignedFromDb;
      if (googleCreditsCharged || googleSynced < 1) return;
      googleCreditsCharged = true;
      console.log("[syncLeadsFront] charging credits", {
        googleSynced,
        created,
        alreadyInDb,
        syncedThisRequest,
        assignedFromDb,
      });
      // #region agent log
      fetch('http://127.0.0.1:7352/ingest/c13a22b4-961b-4030-9e07-9a1b167ba855',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'0a11d1'},body:JSON.stringify({sessionId:'0a11d1',runId:'post-fix',hypothesisId:'credits',location:'syncLeadsFront.ts:chargeCredits',message:'Consuming credits for Google-synced leads',data:{googleSynced,created,alreadyInDb,syncedThisRequest,assignedFromDb},timestamp:Date.now()})}).catch(()=>{});
      // #endregion
      const consumeResult = await consumeCompanyCredits(context, {
        companyId: company.id,
        amount: googleSynced,
        referenceType: "sync",
        notes: "Leads sincronizados desde Google Maps",
      });
      if (consumeResult.success) {
        currentSyncedCount = consumeResult.syncedCount;
      } else {
        console.warn("[syncLeadsFront] credit consume failed", {
          googleSynced,
          syncedCount: consumeResult.syncedCount,
          leadLimit: consumeResult.leadLimit,
        });
      }
    };

    type NearbyPlace = {
      place_id: string;
      rating?: number;
      user_ratings_total?: number;
    };

    try {
      // --- Fase 1: recaudar páginas Nearby YA (antes de Place Details).
      // El pagetoken de Google se invalida si esperamos demasiado (p.ej. details).
      // Una sola espera de 2s entre páginas; sin reintentos. Máx 3 páginas (= 60).
      const PAGE_TOKEN_DELAY_MS = 2000;
      const MAX_NEARBY_PAGES = 3;
      const nearbyPlaces: NearbyPlace[] = [];
      const seenPlaceIds = new Set<string>();
      let pageToken: string | undefined;
      let firstPageError: string | null = null;

      for (
        let page = 0;
        page < MAX_NEARBY_PAGES && nearbyPlaces.length < maxResults;
        page++
      ) {
        if (pageToken) {
          await new Promise((r) => setTimeout(r, PAGE_TOKEN_DELAY_MS));
        }

        const url = pageToken
          ? `https://maps.googleapis.com/maps/api/place/nearbysearch/json?pagetoken=${pageToken}&key=${apiKey}`
          : `https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${lat},${lng}&radius=${radiusMeters}&keyword=${keyword}&key=${apiKey}&language=es`;

        // #region agent log
        const urlForLog = url.replace(/key=[^&]+/, "key=REDACTED");
        console.log("[syncLeadsFront] GOOGLE page fetch", {
          page: page + 1,
          hasPageToken: !!pageToken,
          collectedSoFar: nearbyPlaces.length,
          url: urlForLog,
        });
        fetch('http://127.0.0.1:7352/ingest/c13a22b4-961b-4030-9e07-9a1b167ba855',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'0a11d1'},body:JSON.stringify({sessionId:'0a11d1',runId:'post-fix',hypothesisId:'pages-first',location:'syncLeadsFront.ts:pageFetch',message:'Fetching nearby page before details',data:{page:page+1,hasPageToken:!!pageToken,collectedSoFar:nearbyPlaces.length},timestamp:Date.now()})}).catch(()=>{});
        // #endregion

        const res = await fetch(url);
        const data = (await res.json()) as {
          status?: string;
          error_message?: string;
          results?: NearbyPlace[];
          next_page_token?: string;
        };

        // #region agent log
        console.log("[syncLeadsFront] GOOGLE page response", {
          page: page + 1,
          googleStatus: data?.status,
          resultsCount: Array.isArray(data?.results) ? data.results.length : 0,
          hasNextPageToken: !!data?.next_page_token,
        });
        fetch('http://127.0.0.1:7352/ingest/c13a22b4-961b-4030-9e07-9a1b167ba855',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'0a11d1'},body:JSON.stringify({sessionId:'0a11d1',runId:'post-fix',hypothesisId:'pages-first',location:'syncLeadsFront.ts:pageResponse',message:'Nearby page response',data:{page:page+1,googleStatus:data?.status,resultsCount:Array.isArray(data?.results)?data.results.length:0,hasNextPageToken:!!data?.next_page_token},timestamp:Date.now()})}).catch(()=>{});
        // #endregion

        if (data.status !== "OK" && data.status !== "ZERO_RESULTS") {
          if (page === 0) {
            firstPageError = data.error_message || data.status || "INVALID_REQUEST";
            break;
          }
          console.warn(
            "[syncLeadsFront] stopping pagination (keeping prior pages)",
            { page: page + 1, googleStatus: data.status },
          );
          break;
        }

        for (const place of data.results || []) {
          if (!place?.place_id || seenPlaceIds.has(place.place_id)) continue;
          seenPlaceIds.add(place.place_id);
          nearbyPlaces.push(place);
          if (nearbyPlaces.length >= maxResults) break;
        }

        pageToken = data.next_page_token;
        if (!pageToken) break;
      }

      if (firstPageError && nearbyPlaces.length === 0) {
        const result = {
          success: false,
          message: firstPageError,
          created,
          alreadyInDb,
          skippedLowRating,
          syncedLeadsCount: syncedThisRequest,
          syncedCount: currentSyncedCount,
          leadLimit,
        };
        await logSyncLeadsResult(context, userId, company.id, input, result);
        return result;
      }

      console.log("[syncLeadsFront] GOOGLE places collected", {
        total: nearbyPlaces.length,
      });

      // --- Fase 2: Place Details + crear/asignar en BD
      for (const place of nearbyPlaces) {
        if (syncedThisRequest >= maxResults) break;
        if (leadLimit !== null && currentSyncedCount >= leadLimit) break;

        const placeId = place.place_id;
        const placeRating = place.rating ?? 0;
        const userRatingsTotal = place.user_ratings_total ?? 0;

        let lead = await context.sudo().query.TechBusinessLead.findOne({
          where: { googlePlaceId: placeId },
          query: "id saasCompany { id }",
        });

        if (lead) {
          const leadCompanies =
            (lead as { id: string; saasCompany?: { id: string }[] })
              .saasCompany ?? [];
          const alreadyAssignedToThisCompany = leadCompanies.some(
            (c) => c.id === company.id,
          );
          if (alreadyAssignedToThisCompany) {
            continue;
          }
          alreadyInDb++;
          try {
            const leadId = (lead as { id: string }).id;
            await context.sudo().query.TechBusinessLead.updateOne({
              where: { id: leadId },
              data: { saasCompany: { connect: { id: company.id } } },
            });
            const level: "Alta" | "Media" | "Baja" =
              placeRating >= 4.5
                ? "Alta"
                : placeRating >= 4
                  ? "Media"
                  : "Baja";
            await ensureStatusForLeadAssignment(
              context,
              leadId,
              company.id,
              userId,
              level,
            );
            syncedThisRequest++;
            currentSyncedCount++;
          } catch (_) {}
          continue;
        }

        if (placeRating < minRating || userRatingsTotal < minReviews) {
          skippedLowRating++;
          continue;
        }

        console.log("[syncLeadsFront] getPlaceDetails", {
          placeId,
          placeRating,
          userRatingsTotal,
        });
        const details = await getPlaceDetails(placeId, apiKey);
        if (!details) {
          console.warn("[syncLeadsFront] getPlaceDetails returned null", {
            placeId,
          });
          continue;
        }

        const {
          city: parsedCity,
          state,
          country,
        } = parseAddressComponents(details.address_components || []);
        const { topReviews, websitePromptContent } = buildReviewsAndPrompt(
          details,
          category,
        );

        const leadData: Record<string, unknown> = {
          businessName: details.name,
          category,
          phone:
            details.formatted_phone_number ||
            details.international_phone_number ||
            "",
          address: details.formatted_address || "",
          city: parsedCity || "",
          state: state || "",
          country: country || "",
          rating: details.rating ?? null,
          reviewCount: details.user_ratings_total ?? null,
          hasWebsite: !!details.website,
          websiteUrl: details.website || "",
          source: "Google Maps",
          googlePlaceId: placeId,
          googleMapsUrl: `https://www.google.com/maps/place/?q=place_id:${placeId}`,
          topReview1: topReviews[0] || null,
          topReview2: topReviews[1] || null,
          topReview3: topReviews[2] || null,
          topReview4: topReviews[3] || null,
          topReview5: topReviews[4] || null,
          websitePromptContent,
          saasCompany: { connect: { id: company.id } },
          lat: details.geometry?.location?.lat ?? null,
          lng: details.geometry?.location?.lng ?? null,
        };

        try {
          const newLead = await context.sudo().query.TechBusinessLead.createOne({
            data: leadData as any,
          });
          await context.sudo().query.TechStatusBusinessLead.createOne({
            data: {
              businessLead: { connect: { id: newLead.id } },
              saasCompany: { connect: { id: company.id } },
              salesPerson: { connect: { id: userId } },
              pipelineStatus: PIPELINE_STATUS.DETECTADO,
              opportunityLevel:
                placeRating >= 4.5
                  ? "Alta"
                  : placeRating >= 4
                    ? "Media"
                    : "Baja",
            },
          });
          created++;
          syncedThisRequest++;
          currentSyncedCount++;
        } catch (_) {
          // skip on duplicate or validation error
        }
      }

      await chargeGoogleCreditsIfNeeded();

      const result = {
        success: true,
        message: `Sincronización completada. Leads asignados a tu empresa: ${syncedThisRequest} ${leadLimit !== null ? ` Cuota: ${currentSyncedCount}/${leadLimit} este mes.` : ""}`,
        created,
        alreadyInDb,
        skippedLowRating,
        syncedLeadsCount: syncedThisRequest,
        syncedCount: currentSyncedCount,
        leadLimit,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    } catch (err) {
      console.error("[syncLeadsFront] EXCEPTION in Google sync", err);
      await chargeGoogleCreditsIfNeeded();
      const result = {
        success: false,
        message: err instanceof Error ? err.message : "Error en sincronización",
        created,
        alreadyInDb,
        skippedLowRating,
        syncedLeadsCount: syncedThisRequest,
        syncedCount: currentSyncedCount,
        leadLimit,
      };
      await logSyncLeadsResult(context, userId, company.id, input, result);
      return result;
    }
  },
};

export default { typeDefs, definition, resolver };
