/** Marca del correo de "nuevo post": cada producto tiene su propio blog y audiencia. */
const NEW_POST_EMAIL_BRANDS = {
  pet: { name: "Kadesh Pet", color: "#FF8C42", hover: "#E67A35" },
  saas: { name: "Kadesh Negocios", color: "#FF8C42", hover: "#E67A35" },
} as const;

export type NewPostEmailBrand = keyof typeof NEW_POST_EMAIL_BRANDS;

/**
 * Send email notification for new blog post
 */
export async function sendNewPostEmail({
  postTitle,
  postUrl,
  postExcerpt,
  authorName,
  categoryName,
  recipientEmails,
  brand = "pet",
  unsubscribeBaseUrl,
}: {
  postTitle: string;
  postUrl: string;
  postExcerpt?: string | null;
  authorName?: string | null;
  categoryName?: string | null;
  recipientEmails: string[];
  brand?: NewPostEmailBrand;
  /** Página del front donde se da de baja; se le agrega `?email=` de cada destinatario. */
  unsubscribeBaseUrl?: string;
}): Promise<void> {
  if (recipientEmails.length === 0) {
    return;
  }

  const { name: brandName, color, hover } = NEW_POST_EMAIL_BRANDS[brand];
  const subject = `Nuevo artículo en ${brandName}: ${postTitle}`;

  const buildHtml = (unsubscribeUrl: string | null) => `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <meta name="color-scheme" content="dark">
      <style>
        body {
          font-family: Arial, sans-serif;
          line-height: 1.6;
          color: #BBBBBB;
          background-color: #1A1A1A;
          max-width: 600px;
          margin: 0 auto;
          padding: 20px;
        }
        .header {
          background-color: ${color};
          color: #FFFFFF;
          padding: 20px;
          text-align: center;
          border-radius: 5px 5px 0 0;
        }
        .header h1 {
          margin: 0;
          font-size: 22px;
        }
        .content {
          background-color: #2C2C2C;
          padding: 20px;
          border-radius: 0 0 5px 5px;
          border: 1px solid #404040;
          border-top: none;
        }
        .post-title {
          font-size: 24px;
          font-weight: bold;
          margin-bottom: 15px;
          color: #FFFFFF;
        }
        .post-excerpt {
          font-size: 16px;
          color: #BBBBBB;
          margin-bottom: 20px;
          line-height: 1.8;
        }
        .post-meta {
          font-size: 14px;
          color: #87CEEB;
          margin-bottom: 20px;
        }
        .button {
          display: inline-block;
          padding: 12px 30px;
          background-color: ${color};
          color: #FFFFFF;
          text-decoration: none;
          border-radius: 5px;
          font-weight: bold;
          margin-top: 20px;
        }
        .button:hover {
          background-color: ${hover};
        }
        .footer {
          margin-top: 30px;
          padding-top: 20px;
          border-top: 1px solid #404040;
          font-size: 12px;
          color: #BBBBBB;
          text-align: center;
        }
        .footer a {
          color: #87CEEB;
          text-decoration: underline;
        }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>¡Nuevo artículo en ${brandName}!</h1>
      </div>
      <div class="content">
        <div class="post-title">${postTitle}</div>
        ${postExcerpt ? `<div class="post-excerpt">${postExcerpt}</div>` : ""}
        <div class="post-meta">
          ${authorName ? `<strong>Autor:</strong> ${authorName}<br>` : ""}
          ${categoryName ? `<strong>Categoría:</strong> ${categoryName}` : ""}
        </div>
        <a href="${postUrl}" class="button">Leer Post Completo</a>
      </div>
      <div class="footer">
        <p>Gracias por suscribirte a nuestro blog.</p>
        ${
          unsubscribeUrl
            ? `<p>Si no deseas recibir más notificaciones, <a href="${escapeHtml(unsubscribeUrl)}">cancela tu suscripción aquí</a>.</p>`
            : `<p>Si no deseas recibir más notificaciones, puedes cancelar tu suscripción en cualquier momento.</p>`
        }
      </div>
    </body>
    </html>
  `;

  for (const email of recipientEmails) {
    const unsubscribeUrl = unsubscribeBaseUrl
      ? `${unsubscribeBaseUrl}?email=${encodeURIComponent(email)}`
      : null;

    await sendEmail({
      to: email,
      subject,
      html: buildHtml(unsubscribeUrl),
      fromName: brandName,
    });
  }
}

function formatReleaseBodyHtml(body: string | null | undefined): string {
  if (!body?.trim()) {
    return "";
  }

  return escapeHtml(body.trim())
    .replace(/\n{2,}/g, "</p><p style=\"margin:0 0 12px 0;font-size:15px;line-height:1.65;color:#475569;\">")
    .replace(/\n/g, "<br>");
}

function releaseProductLabel(product: SystemReleaseProduct): string {
  if (product === SYSTEM_RELEASE_PRODUCT.PET) return "Pet";
  if (product === SYSTEM_RELEASE_PRODUCT.SAAS) return "Negocios";
  return "Kadesh";
}

